430	        owner.setHouseholdId(householdId(owner));
431	        owner.setNamesakeCount(countNamesakes(owner));
432	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
433	        if (declaredMember) {
434	            owner.setPossibleDuplicate(false);
435	            owner.setPossibleDuplicateOf(null);
436	        } else {
437	            assignPossibleDuplicate(owner);
438	        }
439	    }
440	
441	    /**
442	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
443	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
444	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
445	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
446	     * which case the owner is created as a declared household member.
447	     */
448	    private boolean hasExistingHousehold(Owner owner) {
449	        return !findHousemates(owner).isEmpty();
450	    }
451	
452	    /**
453	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
454	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
455	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
456	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
457	     * to the matching owner's id. Runs before save, against the existing owner population.
458	     */
459	    private void assignPossibleDuplicate(Owner owner) {
460	        Integer matchId = findPossibleDuplicateOf(owner);
461	        owner.setPossibleDuplicate(matchId != null);
462	        owner.setPossibleDuplicateOf(matchId);
463	    }
464	
465	    /**
466	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
467	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
468	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
469	     * never matches.
470	     */
471	    private Integer findPossibleDuplicateOf(Owner owner) {
472	        String postcode = owner.getPostcode();
473	        if (postcode == null) {
474	            return null;
475	        }
476	        String lastName = normalizeHouseholdField(owner.getLastName());
477	        String telephone = owner.getTelephone();
478	        return this.clinicService.findAllOwners().stream()
479	            .filter(existing -> existing.getId() != null
480	                && postcode.equals(existing.getPostcode())
481	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
482	                && !telephone.equals(existing.getTelephone()))
483	            .map(Owner::getId)
484	            .min(Integer::compareTo)
485	            .orElse(null);
486	    }
487	
488	    /**
489	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
490	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
491	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
492	     * owner's last name (e.g. 'NSW-1A2B3C4D'). There are no sequence numbers: the identity is a pure
493	     * function of the region and the (telephone, last name) pair.
494	     */
495	    private String generateCustomerCode(Owner owner) {
496	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
497	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
498	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
499	        return owner.getRegion() + "-" + hash8;
500	    }
501	
502	    /**
503	     * The number of existing owners registered in {@code city}, compared case-insensitively
504	     * with collapsed whitespace.
505	     */
506	    private int countOwnersInCity(String city) {
507	        String normalized = normalizeHouseholdField(city);
508	        return (int) this.clinicService.findAllOwners().stream()
509	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
510	            .count();
511	    }
512	
513	    /**
514	     * The effective registration date to store for a new owner: the date supplied on the request
515	     * when present, otherwise the current server date, in either case rolled forward to a business
516	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
517	     * This single point of resolution is what every registration-date-derived value (the stored
518	     * date, the membership number's year segment, the per-day create-limit) is computed from.
519	     */
520	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
521	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
522	        return toBusinessDay(date);
523	    }
524	
525	    /**
526	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
527	     * following Monday; a weekday is returned unchanged.
528	     */
529	    private static LocalDate toBusinessDay(LocalDate date) {
530	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
531	            date = date.plusDays(1);
532	        }
533	        return date;
534	    }
535	
536	    /**
537	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
538	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
539	     */
540	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
541	        String yy = String.format("%02d", registrationDate.getYear() % 100);
542	        return customerCode + "-M" + yy;
543	    }
544	
545	    /**
546	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
547	     * last name, compared case-insensitively.
548	     */
549	    private int countNamesakes(Owner owner) {
550	        String firstName = normalizeHouseholdField(owner.getFirstName());
551	        String lastName = normalizeHouseholdField(owner.getLastName());
552	        return (int) this.clinicService.findAllOwners().stream()
553	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
554	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
555	            .count();
556	    }
557	
558	    /**
559	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
560	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
561	     * unusually high daily signup volume.
562	     */
563	    private boolean isBulkSignupWarning() {
564	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
565	    }
566	
567	    /** The number of existing owners whose registration date is {@code date}. */
568	    private int countOwnersRegisteredOn(LocalDate date) {
569	        return (int) this.clinicService.findAllOwners().stream()
570	            .filter(existing -> date.equals(existing.getRegistrationDate()))
571	            .count();
572	    }
573	
574	    /**
575	     * The single derived key all duplicate detection flows through, formed from the owner's
576	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
577	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
578	     * id is derived, so the household segment is empty at that point. Because the telephone is part
579	     * of the key, two owners in the same household with different telephones resolve to different
580	     * keys and are both allowed.
581	     */
582	    private static String identityKey(Owner owner) {
583	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
584	        String email = owner.getEmail() == null ? "" : owner.getEmail();
585	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
586	        return telephone + "|" + email + "|" + household;
587	    }
588	
589	    /**
590	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
591	     * duplicate condition: the previously separate telephone, email and household checks are now all
592	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
593	     * trips it is rejected with {@code 409 CONFLICT}.
594	     */
595	    private boolean isDuplicate(Owner owner) {
596	        String key = owner.getIdentityKey();
597	        return this.clinicService.findAllOwners().stream()
598	            .map(Owner::getIdentityKey)
599	            .filter(existing -> existing != null)
600	            .anyMatch(key::equals);
601	    }
602	
603	    /** Common street-type abbreviations expanded during address normalization. */
604	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
605	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
606	
607	    /**
608	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
609	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
610	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
611	     * string when {@code address} is null or blank after normalization.
612	     */
613	    private static String normalizeAddress(String address) {
614	        if (address == null) {
615	            return "";
616	        }
617	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
618	        if (collapsed.isEmpty()) {
619	            return "";
620	        }
621	        StringBuilder sb = new StringBuilder(collapsed.length());
622	        for (String token : collapsed.split(" ")) {
623	            if (sb.length() > 0) {
624	                sb.append(' ');
625	            }
626	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
627	        }
628	        return sb.toString();
629	    }
630	
631	    /**
632	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
633	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
634	     */
635	    private static String normalizeHouseholdField(String value) {
636	        if (value == null) {
637	            return "";
638	        }
639	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
640	    }
641	
642	    /**
643	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
644	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
645	     * key rather than re-derived from the underlying fields here, so the household is described in one
646	     * place and every household-keyed value stays consistent with it.
647	     */
648	    private List<Owner> findHousemates(Owner owner) {
649	        String householdId = householdId(owner);
650	        return this.clinicService.findAllOwners().stream()
651	            .filter(existing -> householdId(existing).equals(householdId))
652	            .toList();
653	    }
654	
655	    /**
656	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
657	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
658	     */
659	    private int countHouseholdMembers(Owner owner) {
660	        return findHousemates(owner).size() + 1;
661	    }
662	
663	    /**
664	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
665	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
666	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
667	     * string standing in for a missing postcode), so housemates always resolve to the same value
668	     * regardless of registration order, and owners sharing a last name and postcode share it
669	     * automatically.
670	     */
671	    private static String householdId(Owner owner) {
672	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
673	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
674	        return sha256Hex(key).substring(0, 12);
675	    }
676	
677	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
678	    private static String sha256Hex(String input) {
679	        try {
680	            byte[] digest = MessageDigest.getInstance("SHA-256")
681	                .digest(input.getBytes(StandardCharsets.UTF_8));
682	            StringBuilder sb = new StringBuilder(digest.length * 2);
683	            for (byte b : digest) {
684	                sb.append(String.format("%02X", b));
685	            }
686	            return sb.toString();
687	        }
688	        catch (NoSuchAlgorithmException e) {
689	            throw new IllegalStateException("SHA-256 not available", e);
690	        }
691	    }
692	}
